document.addEventListener("DOMContentLoaded",function(){const slider=document.querySelector(".slider");const slides=document.querySelectorAll(".slider__item");const slides2=document.querySelectorAll(".slider__item .slider__text-image, .slider__item .slider__accordion");const prevButton=document.querySelector(".slider__prev");const nextButton=document.querySelector(".slider__next");let currentIndex=0;let startX,endX;const totalSlides=slides.length;const counterLine=document.querySelector(".slider__counter-line");const counterNum=document.querySelector(".slider__counter-num");const stepSize=(94-41)/(totalSlides-1);var maxSlideHeight=0;var animationTime=500;const slideIntervalTime=3e4;let slideInterval;slides.forEach((slide,index)=>{slide.style.left=`${index*100}%`;if(maxSlideHeight<slide.scrollHeight)maxSlideHeight=slide.scrollHeight});const accordion_slides=document.querySelectorAll(".slider__item--accordion");slides.forEach((slide,index)=>{slide.style.minHeight=`${maxSlideHeight}px`});var accordionItems=document.querySelectorAll(".slider__accordion-item");accordionItems.forEach(function(item){item.addEventListener("click",function(){this.classList.toggle("active");animationTime=500;updateSliderHeight()})});function updateCounterLine(index){const newPosition=index*stepSize;counterLine.style.setProperty("--counter-line-position",`${newPosition}px`)}function updateCounterNum(index){counterNum.textContent=String(index+1).padStart(2,"0")}function showSlide(index){const offset=index*-100;slides.forEach((slide,i)=>{slide.style.transition="transform 0.5s ease-in-out";slide.style.transform=`translateX(${offset}%)`;if(i===index){slide.classList.add("active")}else{slide.classList.remove("active")}});updateSliderHeight();updateCounterLine(index);updateCounterNum(index)}function updateSliderHeight(){const activeSlide=document.querySelector(".slider__item.active");slides.forEach((slide,index)=>{if(maxSlideHeight<slide.scrollHeight)maxSlideHeight=slide.scrollHeight});if(activeSlide){slider.style.height=`${activeSlide.scrollHeight}px`}if(animationTime>0)setTimeout(updateSliderHeight,1);animationTime--}function startSlideInterval(){slideInterval=setInterval(()=>{currentIndex=(currentIndex+1)%slides.length;showSlide(currentIndex)},slideIntervalTime)}function stopSlideInterval(){clearInterval(slideInterval)}nextButton.addEventListener("click",()=>{stopSlideInterval();currentIndex=(currentIndex+1)%slides.length;showSlide(currentIndex);startSlideInterval()});prevButton.addEventListener("click",()=>{stopSlideInterval();currentIndex=(currentIndex-1+slides.length)%slides.length;showSlide(currentIndex);startSlideInterval()});slider.addEventListener("touchstart",function(e){stopSlideInterval();startX=e.touches[0].pageX});slider.addEventListener("touchend",function(e){endX=e.changedTouches[0].pageX;handleSwipe();startSlideInterval()});slider.addEventListener("mousedown",function(e){stopSlideInterval();startX=e.pageX;slider.style.cursor="grabbing"});slider.addEventListener("mouseup",function(e){endX=e.pageX;slider.style.cursor="grab";handleSwipe();startSlideInterval()});function handleSwipe(){if(startX-endX>100){currentIndex=(currentIndex+1)%slides.length}else if(endX-startX>100){currentIndex=(currentIndex-1+slides.length)%slides.length}showSlide(currentIndex)}showSlide(currentIndex);window.addEventListener("resize",updateSliderHeight);startSlideInterval()});